// Pseudo-code: allocate and free with size classes 16/32/64
struct Block { Block* next; };
class Allocator {
  std::atomic<Block*> globalFree[3];
  thread_local Block* localFree[3];
  int size_to_index(size_t s);
  void* allocate(size_t sz); // uses localFree, spills to globalFree with CAS
  void free(void* p, size_t sz); // pushes to localFree, retires via hazard pointers
};
